<?php require "config.php";require_admin();$id=filter_input(INPUT_GET,"id",FILTER_VALIDATE_INT);if(!$id){header("Location: dashboard.php");exit;}$s=$conn->prepare("SELECT * FROM complaints WHERE id=?");$s->bind_param("i",$id);$s->execute();$record=$s->get_result()->fetch_assoc();$s->close();if(!$record)die("Complaint not found.");$allowed=["New","In Review","Action Taken","Closed"];$error="";if($_SERVER["REQUEST_METHOD"]==="POST"){$st=$_POST["status"]??"";$notes=trim($_POST["admin_notes"]??"");if(!in_array($st,$allowed,true))$error="Invalid status.";else{$u=$conn->prepare("UPDATE complaints SET status=?,admin_notes=? WHERE id=?");$u->bind_param("ssi",$st,$notes,$id);if($u->execute()){header("Location: dashboard.php?updated=1");exit;}$error="Update failed.";}}$page_title="Review Complaint | SFHS";require "includes/header.php"; ?>
<h1>Review complaint</h1><div class="grid review"><article class="panel"><span class="badge"><?=e($record["status"])?></span><h2><?=e($record["subject"])?></h2><p class="muted"><?=e($record["tracking_code"])?> · <?=e($record["category"])?></p><h3>Details</h3><p><?=nl2br(e($record["details"]))?></p><h3>Reporter</h3><p><?=$record["is_anonymous"]?"Anonymous":e($record["reporter_name"]??"Not provided")?></p><?php if(!$record["is_anonymous"]): ?><p><?=e($record["reporter_contact"]??"")?></p><?php endif; ?></article><form class="form" method="post"><h2>Update progress</h2><?php if($error): ?><p class="error"><?=e($error)?></p><?php endif; ?><label>Status</label><select name="status"><?php foreach($allowed as $st): ?><option <?=($record["status"]===$st?"selected":"")?>><?=e($st)?></option><?php endforeach; ?></select><label>Internal notes (admin only)</label><textarea name="admin_notes" rows="6"><?=e($record["admin_notes"]??"")?></textarea><button class="btn">Save update</button> <a href="dashboard.php">Cancel</a></form></div><?php require "includes/footer.php"; ?>